using System;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

public class LightningAction : BattleAction
{
	[Header("X Time Specifics")]
	[SerializeField]
	protected bool enableVariableCorruptPurifyAmount;

	[SerializeField]
	[HideIf("enableVariableCorruptPurifyAmount")]
	private int baseCorruptPurifyAmount;

	[NonSerialized]
	public int CorruptPurifyAmountModifier;

	[SerializeField]
	[HideIf("overrideDelayBetweenCorruptPurifyFloatReference")]
	protected FloatReference delayBetweenCorruptPurifyFloatReference;

	[SerializeField]
	private bool overrideDelayBetweenCorruptPurifyFloatReference;

	[SerializeField]
	[ShowIf("overrideDelayBetweenCorruptPurifyFloatReference")]
	private float delayBetweenCorruptPurify;

	[SerializeField]
	protected bool austra;

	public int CorruptPurifyAmountWithModifier => baseCorruptPurifyAmount + CorruptPurifyAmountModifier;

	public float DelayBetweenCorruptPurify
	{
		get
		{
			if (!overrideDelayBetweenCorruptPurifyFloatReference)
			{
				return delayBetweenCorruptPurifyFloatReference.Value;
			}
			return delayBetweenCorruptPurify;
		}
	}

	protected void ActivateSafeCriticalOmen(GameObject source)
	{
		if (austra && ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
		{
			ReferenceSingleton<AustraOmensHandler>.Instance.ActivateSafeCriticalOmen();
		}
	}

	protected void DeactivateSafeCriticalOmen()
	{
		if (austra)
		{
			ReferenceSingleton<AustraOmensHandler>.Instance.DeactivateSafeCriticalOmen();
		}
	}
}
